import json, urllib.request, urllib.error

TOKEN = "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"
OWNER = "ibb142"
REPO = "rork-global-real-estate-invest"
API = "https://api.github.com/repos"

def api(url, method='GET', body=None):
    h = {'Authorization': f'token {TOKEN}', 'Accept': 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28'}
    if body: h['Content-Type'] = 'application/json'
    d = json.dumps(body).encode() if body else None
    req = urllib.request.Request(url, data=d, headers=h, method=method)
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, json.loads(r.read())
    except urllib.error.HTTPError as e:
        raw = e.read()
        return e.code, json.loads(raw) if raw else {}
    except Exception as e:
        return 0, {'error': str(e)}

# Step 1: Confirm workflow file exists on GitHub
print('=== STEP 1: Confirm workflow file exists ===')
s, d = api(f"{API}/{OWNER}/{REPO}/contents/.github/workflows/ivx-ci.yml")
if s == 200:
    print(f'  PASS: .github/workflows/ivx-ci.yml exists')
    print(f'  SHA: {d.get("sha")}')
    print(f'  Size: {d.get("size")} bytes')
    print(f'  URL: {d.get("html_url")}')
else:
    print(f'  FAIL: HTTP {s} — {json.dumps(d)[:300]}')

# Step 2: Return commit SHA (latest commit on main that includes the workflow)
print('\n=== STEP 2: Latest commit SHA ===')
s2, d2 = api(f"{API}/{OWNER}/{REPO}/commits?per_page=5&sha=main")
if s2 == 200:
    for c in d2[:5]:
        msg = c.get('commit',{}).get('message','')[:80]
        print(f'  {c["sha"][:12]} — {msg}')
    # Find the commit that created/modified the workflow
    head_sha = d2[0]['sha']
    print(f'\n  HEAD commit SHA: {head_sha}')
    print(f'  HEAD short SHA: {head_sha[:12]}')
else:
    print(f'  FAIL: HTTP {s2}')

# Step 2b: Verify the workflow is indexed by GitHub Actions
print('\n=== STEP 2b: Workflow indexed by GitHub Actions ===')
s3, d3 = api(f"{API}/{OWNER}/{REPO}/actions/workflows")
if s3 == 200:
    workflows = d3.get('workflows', [])
    for wf in workflows:
        if 'ivx-ci' in wf.get('path',''):
            print(f'  PASS: Workflow indexed')
            print(f'    id: {wf.get("id")}')
            print(f'    name: {wf.get("name")}')
            print(f'    path: {wf.get("path")}')
            print(f'    state: {wf.get("state")}')
            with open('/tmp/workflow_id.txt', 'w') as f:
                f.write(str(wf.get('id')))
else:
    print(f'  FAIL: HTTP {s3} — {json.dumps(d3)[:300]}')
PYEOF"}

