import json, urllib.request, urllib.error

TOKEN = "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"
OWNER = "ibb142"
REPO = "rork-global-real-estate-invest"
API = "https://api.github.com/repos"

def api(url, method='GET', body=None):
    h = {'Authorization': f'token {TOKEN}', 'Accept': 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28'}
    if body: h['Content-Type'] = 'application/json'
    d = json.dumps(body).encode() if body else None
    req = urllib.request.Request(url, data=d, headers=h, method=method)
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            raw = r.read()
            return r.status, json.loads(raw) if raw else {}
    except urllib.error.HTTPError as e:
        raw = e.read()
        return e.code, json.loads(raw) if raw else {}
    except Exception as e:
        return 0, {'error': str(e)}

# Step 3: Trigger workflow_dispatch #1 — backend tests only, no APK
print('=== STEP 3: Trigger workflow_dispatch #1 (backend tests, no APK) ===')
s, d = api(f"{API}/{OWNER}/{REPO}/actions/workflows/ivx-ci.yml/dispatches", 'POST', {
    'ref': 'main',
    'inputs': {
        'testTarget': 'backend/ivx-registration-orchestrator.test.ts backend/ivx-timezone.test.ts',
        'buildApk': 'false'
    }
})
print(f'  HTTP {s}')
if s == 204:
    print('  PASS: Workflow dispatch #1 accepted (HTTP 204)')
else:
    print(f'  FAIL: {json.dumps(d)[:500]}')

# Wait a moment for GitHub to register the run
import time
print('  Waiting 5s for run to register...')
time.sleep(5)

# Get the run ID for this dispatch
s2, d2 = api(f"{API}/{OWNER}/{REPO}/actions/runs?per_page=5&event=workflow_dispatch")
if s2 == 200:
    runs = d2.get('workflow_runs', [])
    for run in runs[:5]:
        print(f'  Run #{run["run_number"]}: id={run["id"]} status={run["status"]} conclusion={run.get("conclusion")} created={run["created_at"][:19]}')
        if run['status'] in ('queued', 'in_progress', 'waiting'):
            with open('/tmp/run1_id.txt', 'w') as f:
                f.write(str(run['id']))
            print(f'  >> Run #1 ID: {run["id"]}')
            print(f'  >> Run #1 URL: {run["html_url"]}')
            break
else:
    print(f'  Failed to list runs: HTTP {s2}')
PYEOF

