import json, urllib.request, urllib.error, time

TOKEN = "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"
OWNER = "ibb142"
REPO = "rork-global-real-estate-invest"
API = "https://api.github.com/repos"

def api(url, method='GET', body=None, timeout=30):
    h = {'Authorization': f'token {TOKEN}', 'Accept': 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28'}
    if body: h['Content-Type'] = 'application/json'
    d = json.dumps(body).encode() if body else None
    req = urllib.request.Request(url, data=d, headers=h, method=method)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            raw = r.read()
            return r.status, json.loads(raw) if raw else {}
    except urllib.error.HTTPError as e:
        raw = e.read()
        return e.code, json.loads(raw) if raw else {}
    except Exception as e:
        return 0, {'error': str(e)}

RUN_ID = "29982866369"

# Poll run #2 until completion
print(f'=== STEP 6: Polling run #2 (id={RUN_ID}) until completion ===')
max_polls = 40
for i in range(max_polls):
    s, d = api(f"{API}/{OWNER}/{REPO}/actions/runs/{RUN_ID}")
    if s != 200:
        print(f'  Poll {i+1}: HTTP {s}')
        time.sleep(15)
        continue
    status = d.get('status')
    conclusion = d.get('conclusion')
    print(f'  Poll {i+1}: status={status} conclusion={conclusion} ({time.strftime("%H:%M:%S")})')
    if status == 'completed':
        print(f'\n  RUN #2 COMPLETED: conclusion={conclusion}')
        print(f'  Run URL: {d.get("html_url")}')
        print(f'  Run number: {d.get("run_number")}')
        print(f'  Head sha: {d.get("head_sha")[:12]}')

        # Get jobs
        s2, d2 = api(f"{API}/{OWNER}/{REPO}/actions/runs/{RUN_ID}/jobs")
        if s2 == 200:
            jobs = d2.get('jobs', [])
            print(f'\n  Jobs ({len(jobs)}):')
            for job in jobs:
                print(f'    {job.get("name")}: status={job.get("status")} conclusion={job.get("conclusion")}')
                steps = job.get('steps', [])
                for step in steps:
                    print(f'      {step.get("name")}: {step.get("conclusion")}')
        break
    time.sleep(15)
else:
    print(f'  TIMEOUT after {max_polls} polls')
PYEOF"}

