import json, urllib.request, urllib.error, base64

TOKEN = "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"
OWNER = "ibb142"
REPO = "rork-global-real-estate-invest"
BRANCH = "main"
API = "https://api.github.com/repos"

def api(url, method='GET', body=None):
    h = {'Authorization': f'token {TOKEN}', 'Accept': 'application/vnd.github+json', 'Content-Type': 'application/json', 'X-GitHub-Api-Version': '2022-11-28'}
    d = json.dumps(body).encode() if body else None
    req = urllib.request.Request(url, data=d, headers=h, method=method)
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            return r.status, json.loads(r.read())
    except urllib.error.HTTPError as e:
        raw = e.read()
        return e.code, json.loads(raw) if raw else {}
    except Exception as e:
        return 0, {'error': str(e)}

# Commit the fixed workflow
s, head = api(f"{API}/{OWNER}/{REPO}/git/ref/heads/{BRANCH}")
head_sha = head['object']['sha']
print(f"HEAD: {head_sha[:12]}")

fpath = ".github/workflows/ivx-ci.yml"
with open(fpath, 'rb') as f:
    content = f.read()

s, blob = api(f"{API}/{OWNER}/{REPO}/git/blobs", 'POST', {
    'content': base64.b64encode(content).decode(),
    'encoding': 'base64'
})
print(f"  blob: {fpath} ({len(content)} bytes)")

s, tree = api(f"{API}/{OWNER}/{REPO}/git/trees", 'POST', {
    'base_tree': head_sha,
    'tree': [{'path': fpath, 'sha': blob['sha'], 'mode': '100644', 'type': 'blob'}]
})
print(f"Tree: {tree['sha'][:12]}")

s, commit = api(f"{API}/{OWNER}/{REPO}/git/commits", 'POST', {
    'message': 'Fix CI workflow — handle testTarget=default as full suite keyword\n\nWhen testTarget is "default" or "all", run the full env-independent test\nsuite instead of passing "default" literally to bun test (which fails because\nno file named "default" exists).',
    'tree': tree['sha'],
    'parents': [head_sha]
})
print(f"Commit: {commit['sha'][:12]}")

s, ref = api(f"{API}/{OWNER}/{REPO}/git/refs/heads/{BRANCH}", 'PATCH', {
    'sha': commit['sha'],
    'force': False
})
print(f"SUCCESS: pushed {commit['sha'][:12]} to {BRANCH}")
with open('/tmp/ci_fix_sha.txt', 'w') as f:
    f.write(commit['sha'])
PYEOF

