import json, urllib.request, urllib.error

TOKEN = "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"
OWNER = "ibb142"
REPO = "rork-global-real-estate-invest"
API = "https://api.github.com/repos"

def api(url, method='GET', body=None):
    h = {'Authorization': f'token {TOKEN}', 'Accept': 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28'}
    if body: h['Content-Type'] = 'application/json'
    d = json.dumps(body).encode() if body else None
    req = urllib.request.Request(url, data=d, headers=h, method=method)
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            raw = r.read()
            if not raw: return r.status, {}
            try: return r.status, json.loads(raw)
            except: return r.status, {'raw': raw.decode('utf-8', errors='replace')[:5000]}
    except urllib.error.HTTPError as e:
        raw = e.read()
        try: return e.code, json.loads(raw) if raw else {}
        except: return e.code, {'raw': raw.decode('utf-8', errors='replace')[:2000]}
    except Exception as e:
        return 0, {'error': str(e)}

# Get the APK job ID from run #2
RUN_ID = "29982866369"
s, d = api(f"{API}/{OWNER}/{REPO}/actions/runs/{RUN_ID}/jobs")
if s == 200:
    jobs = d.get('jobs', [])
    for job in jobs:
        if 'APK' in job.get('name', ''):
            job_id = job['id']
            print(f'APK Job ID: {job_id}')

            # Get logs for this job
            s2, d2 = api(f"{API}/{OWNER}/{REPO}/actions/jobs/{job_id}/logs")
            if isinstance(d2, dict) and d2.get('raw'):
                # Logs are a redirect to a zip file — print what we got
                print(f'  Logs response (HTTP {s2}): {str(d2.get("raw",""))[:500]}')
            elif isinstance(d2, dict):
                print(f'  Logs response: {json.dumps(d2)[:500]}')
            else:
                print(f'  Logs response: {str(d2)[:500]}')

            # Get the "Build release APK" step details
            for step in job.get('steps', []):
                if step.get('name') == 'Build release APK':
                    print(f'\n  Step: {step.get("name")}')
                    print(f'  status={step.get("status")} conclusion={step.get("conclusion")}')
                    print(f'  number={step.get("number")}')
                    break

# Also get run logs (zipped)
s3, d3 = api(f"{API}/{OWNER}/{REPO}/actions/runs/{RUN_ID}/logs")
if s3 == 302 or (isinstance(d3, dict) and 'raw' in d3):
    print(f'\n  Run logs available (redirect to zip)')
elif s3 == 200:
    print(f'\n  Run logs retrieved')
else:
    print(f'\n  Run logs HTTP {s3}: {json.dumps(d3)[:300] if isinstance(d3, dict) else str(d3)[:300]}')
PYEOF

