TOKEN = "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"
OWNER = "ibb142"
REPO = "rork-global-real-estate-invest"
API = "https://api.github.com/repos"

def api(url, method='GET', body=None):
    h = {'Authorization': f'token {TOKEN}', 'Accept': 'application/vnd.github+json', 'X-GitHub-Api-Version': '2022-11-28'}
    if body: h['Content-Type'] = 'application/json'
    d = json.dumps(body).encode() if body else None
    req = urllib.request.Request(url, data=d, headers=h, method=method)
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            raw = r.read()
            if not raw: return r.status, {}
            try: return r.status, json.loads(raw)
            except: return r.status, {'raw': raw.decode('utf-8', errors='replace')[:5000]}
    except urllib.error.HTTPError as e:
        raw = e.read()
        try: return e.code, json.loads(raw) if raw else {}
        except: return e.code, {'raw': raw.decode('utf-8', errors='replace')[:2000]}
    except Exception as e:
        return 0, {'error': str(e)}

# Check ALL recent runs
print('=== ALL RECENT RUNS ===')
s, d = api(f"{API}/{OWNER}/{REPO}/actions/runs?per_page=20")
if s == 200:
    for run in d.get('workflow_runs', [])[:20]:
        print(f'  #{run["run_number"]}: id={run["id"]} event={run.get("event")} status={run["status"]} conclusion={run.get("conclusion")} sha={run.get("head_sha","")[:12]}')

# Check run #15 (dispatch #3 on fixed commit) in detail
RUN_ID = "29983279458"
print(f'\n=== Run #15 ({RUN_ID}) ===')
s2, d2 = api(f"{API}/{OWNER}/{REPO}/actions/runs/{RUN_ID}")
if s2 == 200:
    print(f'  status={d2.get("status")} conclusion={d2.get("conclusion")}')
    print(f'  URL: {d2.get("html_url")}')
    print(f'  Head SHA: {d2.get("head_sha","")[:12]}')
    print(f'  Created: {d2.get("created_at","")[:19]}')
    print(f'  Updated: {d2.get("updated_at","")[:19]}')

s3, d3 = api(f"{API}/{OWNER}/{REPO}/actions/runs/{RUN_ID}/jobs")
if s3 == 200:
    for job in d3.get('jobs', []):
        print(f'\n  Job: {job.get("name")} → status={job.get("status")} conclusion={job.get("conclusion")}')
        for step in job.get('steps', []):
            print(f'    {step.get("name")}: {step.get("conclusion")}')

# If completed, get artifacts
if d2.get("status") == "completed":
    s4, d4 = api(f"{API}/{OWNER}/{REPO}/actions/runs/{RUN_ID}/artifacts")
    if s4 == 200:
        arts = d4.get('artifacts', [])
        print(f'\n  Artifacts: {len(arts)}')
        for a in arts:
            print(f'    name={a.get("name")} size={a.get("size_in_bytes")} id={a.get("id")}')
            print(f'    download_url={a.get("archive_download_url","")[:100]}')
            print(f'    expired={a.get("expired")} expires_at={a.get("expires_at","")[:19]}')
