OWNER = "ibb142"
REPO = "rork-global-real-estate-invest"
BRANCH = "main"
API = "https://api.github.com/repos"

def api(url, method='GET', body=None):
    h = {'Authorization': f'token {TOKEN}', 'Accept': 'application/vnd.github+json', 'Content-Type': 'application/json', 'X-GitHub-Api-Version': '2022-11-28'}
    d = json.dumps(body).encode() if body else None
    req = urllib.request.Request(url, data=d, headers=h, method=method)
    try:
        with urllib.request.urlopen(req, timeout=30) as r:
            raw = r.read()
            if not raw: return r.status, {}
            try: return r.status, json.loads(raw)
            except: return r.status, {'raw': raw.decode('utf-8', errors='replace')[:3000]}
    except urllib.error.HTTPError as e:
        raw = e.read()
        try: return e.code, json.loads(raw) if raw else {}
        except: return e.code, {'raw': raw.decode('utf-8', errors='replace')[:1000]}
    except Exception as e:
        return 0, {'error': str(e)}

# Commit the workflow fix (Android SDK setup)
print('=== COMMITTING WORKFLOW FIX (Android SDK setup) ===')
s, head = api(f"{API}/{OWNER}/{REPO}/git/ref/heads/{BRANCH}")
head_sha = head['object']['sha']
print(f'HEAD: {head_sha[:12]}')

fpath = ".github/workflows/ivx-ci.yml"
with open(fpath, 'rb') as f:
    content = f.read()

s, blob = api(f"{API}/{OWNER}/{REPO}/git/blobs", 'POST', {
    'content': base64.b64encode(content).decode(),
    'encoding': 'base64'
})

s, tree = api(f"{API}/{OWNER}/{REPO}/git/trees", 'POST', {
    'base_tree': head_sha,
    'tree': [{'path': fpath, 'sha': blob['sha'], 'mode': '100644', 'type': 'blob'}]
})

s, commit = api(f"{API}/{OWNER}/{REPO}/git/commits", 'POST', {
    'message': 'Fix CI APK build — add android-actions/setup-android@v3 for Android SDK\n\nubuntu-latest does not include the Android SDK. Added setup-android action\nwith platform-tools, android-35 platform, and build-tools 35.0.0.',
    'tree': tree['sha'],
    'parents': [head_sha]
})
print(f'Commit: {commit["sha"][:12]}')

s, ref = api(f"{API}/{OWNER}/{REPO}/git/refs/heads/{BRANCH}", 'PATCH', {'sha': commit['sha'], 'force': False})
print(f'Pushed: {commit["sha"][:12]}')

# Wait for push-triggered run to register
time.sleep(5)

# Trigger dispatch #4 with default tests + APK on the fixed commit
print('\n=== TRIGGERING DISPATCH #4 (default tests + APK, Android SDK fix) ===')
s2, d2 = api(f"{API}/{OWNER}/{REPO}/actions/workflows/ivx-ci.yml/dispatches", 'POST', {
    'ref': 'main',
    'inputs': {'testTarget': 'default', 'buildApk': 'true'}
})
print(f'Dispatch #4: HTTP {s2} {"PASS" if s2 == 204 else "FAIL"}')

time.sleep(5)

# Get the new run ID
s3, d3 = api(f"{API}/{OWNER}/{REPO}/actions/runs?per_page=5&event=workflow_dispatch")
if s3 == 200:
    for run in d3.get('workflow_runs', [])[:5]:
        print(f'  Run #{run["run_number"]}: id={run["id"]} status={run["status"]} sha={run.get("head_sha","")[:12]} created={run["created_at"][:19]}')
        if run['status'] in ('queued', 'in_progress', 'waiting'):
            print(f'\n  >> Dispatch #4 Run ID: {run["id"]}')
            print(f'  >> Run URL: {run["html_url"]}')
